window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-27401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιρηγενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1822 na letra μ · nº geral 27401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nascido para um destino feliz; favorito da sorte; filho do destino. 〈μοίρη, γένος〉</p></section></article>\n<article id=\"entry-dgp-27402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιρίδιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1823 na letra μ · nº geral 27402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">marcado pelo destino; fatal. 〈μοῖρα〉</p></section></article>\n<article id=\"entry-dgp-27403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μοῖρις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 1824 na letra μ · nº geral 27403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ιδος dat. jôn. Μοῖρι (ὁ) Moiris, rei do Egito.</p></section></article>\n<article id=\"entry-dgp-27404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιρόκραντος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1825 na letra μ · nº geral 27404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fixado pelo destino ou pelas Moiras; fatal. 〈μοῖρα, κραίνω〉</p></section></article>\n<article id=\"entry-dgp-27405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μοῖσα</h1><div class=\"entry-meta\"><span>DGP · ordem 1826 na letra μ · nº geral 27405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">eól. e lír. = Μοῦσα.</p></section></article>\n<article id=\"entry-dgp-27406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχαλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1827 na letra μ · nº geral 27406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. 1 mulher adúltera 2 adultério. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχάγρια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1828 na letra μ · nº geral 27407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">multa por flagrante adultério. 〈μοιχός, ἀγρέω〉</p></section></article>\n<article id=\"entry-dgp-27408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1829 na letra μ · nº geral 27408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 seduzir; dominar: παύσει αὐτὸν μοιχῶντα τὴν θάλατταν xen. porás fim ao domínio dele no mar 2 falsificar; alterar ♦ méd. 3 bíbl. cometer adultério. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1830 na letra μ · nº geral 27409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adultério. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχεύτρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1831 na letra μ · nº geral 27410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mulher adúltera. 〈μοιχεύω〉</p></section></article>\n<article id=\"entry-dgp-27411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1832 na letra μ · nº geral 27411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cometer adultério; manter ligação adúltera 2 corromper; seduzir; praticar adultério com uma mulher casada, ac. ♦ pas. 3 (mulher) deixar-se seduzir. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχίδιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1833 na letra μ · nº geral 27412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do adultério 2 nascido de um adultério; adulterino. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1834 na letra μ · nº geral 27413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 do adultério; que concerne ao adultério ou ao adúltero 2 propenso ao adultério. 〈μοιχός〉</p></section></article>\n<article id=\"entry-dgp-27414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοιχός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1835 na letra μ · nº geral 27414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homem adúltero.</p></section></article>\n<article id=\"entry-dgp-27415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 1836 na letra μ · nº geral 27415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de βλώσκω.</p></section></article>\n<article id=\"entry-dgp-27416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολίβδινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1837 na letra μ · nº geral 27416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μολύβδινος. 〈μόλιβδος〉</p></section></article>\n<article id=\"entry-dgp-27417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολιβδίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1838 na letra μ · nº geral 27417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μολυβδίς. 〈μόλιβδος〉</p></section></article>\n<article id=\"entry-dgp-27418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλιβδος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1839 na letra μ · nº geral 27418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μόλυβδος.</p></section></article>\n<article id=\"entry-dgp-27419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολιονίδαι, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1840 na letra μ · nº geral 27419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">os filhos de Molion, Ctéato e Êurito. 〈Μολίων〉</p></section></article>\n<article id=\"entry-dgp-27420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλις</h1><div class=\"entry-meta\"><span>DGP · ordem 1841 na letra μ · nº geral 27420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. penosamente; com dificuldade; arduamente: οὐ μόλις sem fadiga, facilmente.</p></section></article>\n<article id=\"entry-dgp-27421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολίων, ονος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1842 na letra μ · nº geral 27421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Molion, troiano.</p></section></article>\n<article id=\"entry-dgp-27422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολόβριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1843 na letra μ · nº geral 27422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhote de javali.</p></section></article>\n<article id=\"entry-dgp-27423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολοβρίτης ὗς (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1844 na letra μ · nº geral 27423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">μολόβριον. 〈μολοβρός〉</p></section></article>\n<article id=\"entry-dgp-27424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολοβρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1845 na letra μ · nº geral 27424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 glutão 2 parasita.</p></section></article>\n<article id=\"entry-dgp-27425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολοσσία,</h1><div class=\"entry-meta\"><span>DGP · ordem 1846 na letra μ · nº geral 27425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Μολοττία, ας (ἡ) Molóssia, região do Epiro.</p></section></article>\n<article id=\"entry-dgp-27426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολοσσικός,</h1><div class=\"entry-meta\"><span>DGP · ordem 1847 na letra μ · nº geral 27426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Μολοττικός, ή, ον 1 do país dos molossos; da Molóssia ♦ οἱ Μολοττικοί 2 cães molossos. 〈Μο­λοσσός〉</p></section></article>\n<article id=\"entry-dgp-27427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολοσσίς,</h1><div class=\"entry-meta\"><span>DGP · ordem 1848 na letra μ · nº geral 27427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Μολοττίς, ίδος (fem.) 1 do país dos molossos ♦ ἡ Μολοσσίς 2 a terra dos molossos; a Molóssia. 〈Μολοσσός〉</p></section></article>\n<article id=\"entry-dgp-27428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολοσσός,</h1><div class=\"entry-meta\"><span>DGP · ordem 1849 na letra μ · nº geral 27428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. Μολοττός, ός, όν 1 do país dos molossos; da Molóssia; molosso; Métr. μολ. πούς molosso, pé formado por três sílabas longas ♦ οἱ Μολοσσοί 2 os molossos.</p></section></article>\n<article id=\"entry-dgp-27429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολοῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1850 na letra μ · nº geral 27429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. βλώσκω.</p></section></article>\n<article id=\"entry-dgp-27430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολπάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1851 na letra μ · nº geral 27430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cantar. 〈μολπή〉</p></section></article>\n<article id=\"entry-dgp-27431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1852 na letra μ · nº geral 27431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dança entremeada de canto 2 canto. 〈μέλπω〉</p></section></article>\n<article id=\"entry-dgp-27432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολπηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1853 na letra μ · nº geral 27432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 como um canto 2 com cantos ou danças. 〈μολπή, -δόν〉</p></section></article>\n<article id=\"entry-dgp-27433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολύβδαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1854 na letra μ · nº geral 27433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chumbo; galena 2 pedaço de chumbo amarrado ao anzol 3 bala de chumbo. 〈μόλυβδος〉</p></section></article>\n<article id=\"entry-dgp-27434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολύβδινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1855 na letra μ · nº geral 27434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de chumbo. 〈μόλυβδος〉</p></section></article>\n<article id=\"entry-dgp-27435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολυβδίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1856 na letra μ · nº geral 27435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 massa ou peso de chumbo 2 bala, projétil de chumbo 3 fio de chumbo. 〈μόλυβδος〉</p></section></article>\n<article id=\"entry-dgp-27436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλυβδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1857 na letra μ · nº geral 27436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chumbo; metal 2 lingote de chumbo usado como pedra de toque para aferir o grau de pureza do ouro 3 peso de chumbo 4 grafite.</p></section></article>\n<article id=\"entry-dgp-27437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολύκρειον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1858 na letra μ · nº geral 27437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Molícrion, cidade e porto da Etólia.</p></section></article>\n<article id=\"entry-dgp-27438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μολυκρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1859 na letra μ · nº geral 27438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Molícrion. 〈Μολύκρειον〉</p></section></article>\n<article id=\"entry-dgp-27439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1860 na letra μ · nº geral 27439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. μολυνῶ, aor. ἐμόλυσα, perf. μεμόλυγκα; perf. pas. μεμόλυμμαι e μεμόλυσμαι) 1 emporcalhar; sujar; manchar 2 transformar em animal: [τὴν Κίρκην] μολύ­νουσάν τε τοὺς ἑταίρους ar. Circe, que faz os companheiros [de Odisseu] transformarem-se em animais 3 tostar a superfície da carne; grelhar a carne ♦ pas. 4 sujar-se pelo contato ou convivência com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-27440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μολυσμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1861 na letra μ · nº geral 27440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de macular, de sujar 2 contaminação. 〈μολύνω〉</p></section></article>\n<article id=\"entry-dgp-27441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόλω, ῃς, ῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 1862 na letra μ · nº geral 27441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de βλώσκω.</p></section></article>\n<article id=\"entry-dgp-27442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μομφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1863 na letra μ · nº geral 27442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 repreensão; censura; recriminação 2 queixa; reclamação: μομφὴν ἔχειν sóf. ter queixa contra alguém, gen. 〈μέμφομαι〉</p></section></article>\n<article id=\"entry-dgp-27443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναδικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1864 na letra μ · nº geral 27443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que diz respeito à unidade 2 Gram. que tem uma só forma para o masculino e para o feminino, como o pron. ἐγώ 3 isolado; solitário. 〈μονάς〉</p></section></article>\n<article id=\"entry-dgp-27444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναδικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1865 na letra μ · nº geral 27444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. isoladamente; individualmente.</p></section></article>\n<article id=\"entry-dgp-27445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονάμπυξ, υκος</h1><div class=\"entry-meta\"><span>DGP · ordem 1866 na letra μ · nº geral 27445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que só tem um frontal (cavalgadura) 2 atrelado sozinho (cavalo). 〈μόνος, ἄμπυξ〉</p></section></article>\n<article id=\"entry-dgp-27446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναρχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1867 na letra μ · nº geral 27446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandar sozinho; reinar soberanamente. 〈μόναρχος〉</p></section></article>\n<article id=\"entry-dgp-27447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναρχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1868 na letra μ · nº geral 27447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 poder de um só homem; governo monárquico; monarquia: λαβών τε χώρας παντελὴ μοναρ­χίαν sóf. tendo assumido o poder absoluto sobre a região 2 comando supremo de um exército 3 em Roma, poder ditatorial. 〈μόναρχος〉</p></section></article>\n<article id=\"entry-dgp-27448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναρχικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1869 na letra μ · nº geral 27448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que concerne ao poder de um só homem; monárquico. 〈μόναρχος〉</p></section></article>\n<article id=\"entry-dgp-27449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναρχικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 1870 na letra μ · nº geral 27449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. monarquicamente; como senhor absoluto.</p></section></article>\n<article id=\"entry-dgp-27450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόναρχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1871 na letra μ · nº geral 27450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que comanda só; soberano ♦ ὁ μόναρ­χος 2 monarca; chefe soberano 3 comandante militar 4 em Roma, ditador. 〈μόνος, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-27451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 1872 na letra μ · nº geral 27451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 só; solitário; isolado ♦ ἡ μο­νάς 2 a unidade. 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναυλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1873 na letra μ · nº geral 27452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tocar um solo de aulos; solar com a flauta. 〈μόνος, αὐλέω〉</p></section></article>\n<article id=\"entry-dgp-27453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναχῆς</h1><div class=\"entry-meta\"><span>DGP · ordem 1874 na letra μ · nº geral 27453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de um só modo; somente.</p></section></article>\n<article id=\"entry-dgp-27454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μοναχός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1875 na letra μ · nº geral 27454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 só; único; simples 2 que vive só; solitário. 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1876 na letra μ · nº geral 27455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de parar; parada 2 permanência; estada 3 demora; retardamento 4 repouso; pausa 5 albergue; pousada 6 bíbl. alojamento 7 crist. monastério. 〈μένω〉</p></section></article>\n<article id=\"entry-dgp-27456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονήμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1877 na letra μ · nº geral 27456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vive ou dura apenas um dia. 〈μό­νος, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-27457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονήρης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1878 na letra μ · nº geral 27457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 simples 2 solitário; isolado 3 singular; peculiar 4 que tem um só homem em cada remo (embarcação). 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονίας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1879 na letra μ · nº geral 27458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vive só; solitário (animal). 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1880 na letra μ · nº geral 27459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que fica no lugar; que permanece fixo 2 estável; duradouro; sólido 3 firme; constante; resoluto. 〈μένω〉</p></section></article>\n<article id=\"entry-dgp-27460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1881 na letra μ · nº geral 27460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e μόνιος, ος, ον 1 solitário; selvagem ♦ ὁ μο­νιός 2 animal selvagem que vive só e não em bando, o javali, o lobo. 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνιππος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1882 na letra μ · nº geral 27461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com um cavalo apenas ♦ ὁ μόνιππος 2 cavalo de sela; cavalo montado. 〈μόνος, ἵππος〉</p></section></article>\n<article id=\"entry-dgp-27462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονογενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1883 na letra μ · nº geral 27462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 unigênito 2 Gram. que tem uma só forma; de uma só origem. 〈μόνος, γένος〉</p></section></article>\n<article id=\"entry-dgp-27463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοδάκτυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1884 na letra μ · nº geral 27463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem apenas um dedo.</p></section></article>\n<article id=\"entry-dgp-27464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόδους, όδοντος</h1><div class=\"entry-meta\"><span>DGP · ordem 1885 na letra μ · nº geral 27464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que tem apenas um dente. 〈μόνος, ὀδούς〉</p></section></article>\n<article id=\"entry-dgp-27465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1886 na letra μ · nº geral 27465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de um só tipo; simples. 〈μόνος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-27466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόζυξ, υγος</h1><div class=\"entry-meta\"><span>DGP · ordem 1887 na letra μ · nº geral 27466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 atrelado só; só 2 solitário; sem consorte 3 que combate só. 〈μόνος, ζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-27467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1888 na letra μ · nº geral 27467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de um só lado. 〈μόνος, -θεν〉</p></section></article>\n<article id=\"entry-dgp-27468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόκερως</h1><div class=\"entry-meta\"><span>DGP · ordem 1889 na letra μ · nº geral 27468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ω (masc., fem.) 1 que tem um chifre só ♦ ὁ μονόκερως gen. ωτος 2 licorne ou unicórnio, animal mitológico. 〈μόνος, κέρας〉</p></section></article>\n<article id=\"entry-dgp-27469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόκλαυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1890 na letra μ · nº geral 27469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que chora ou geme só 2 chorado apenas por um. 〈μόνος, κλαίω〉</p></section></article>\n<article id=\"entry-dgp-27470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόκωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1891 na letra μ · nº geral 27470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Ret. que tem apenas um membro (período) 2 de um só compartimento (construção) 3 de uma única espécie; de uma só origem (nação). 〈μόνος, κῶλον〉</p></section></article>\n<article id=\"entry-dgp-27471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονολεχής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1892 na letra μ · nº geral 27471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dorme só 2 que tem apenas um leito; fiel. 〈μόνος, λέχος〉</p></section></article>\n<article id=\"entry-dgp-27472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόλιθος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1893 na letra μ · nº geral 27472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito com uma só pedra; monólito. 〈μό­νος, λίθος〉</p></section></article>\n<article id=\"entry-dgp-27473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόλυκος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1894 na letra μ · nº geral 27473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lobo solitário, partic. selvagem. 〈μόνος, λύκος〉</p></section></article>\n<article id=\"entry-dgp-27474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1895 na letra μ · nº geral 27474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 combater só, sem socorro, contra alguém, dat. 2 combater em combate singular; combater em duelo contra alguém, dat. ou πρός e ac. 〈μονο­μάχος〉</p></section></article>\n<article id=\"entry-dgp-27475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1896 na letra μ · nº geral 27475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate singular. 〈μονομάχος〉</p></section></article>\n<article id=\"entry-dgp-27476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονομάχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1897 na letra μ · nº geral 27476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que combate só, em combate singular; que se bate em duelo ♦ ὁ μονομάχος 2 gladiador, em Roma. 〈μόνος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-27477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονομερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1898 na letra μ · nº geral 27477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 constituído de apenas uma parte; que forma um todo; simples 2 parcial. 〈μόνος, μέρος〉</p></section></article>\n<article id=\"entry-dgp-27478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόξυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1899 na letra μ · nº geral 27478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito com uma única peça de madeira; de madeira maciça. 〈μόνος, ξύλον〉</p></section></article>\n<article id=\"entry-dgp-27479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόπαις, παιδος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1900 na letra μ · nº geral 27479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho único. 〈μόνος, παῖς〉</p></section></article>\n<article id=\"entry-dgp-27480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόπεπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1901 na letra μ · nº geral 27480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vestido somente com um peplo. 〈μό­νος, πέπλος〉</p></section></article>\n<article id=\"entry-dgp-27481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόρρυθμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1902 na letra μ · nº geral 27481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajustado ou organizado em um só; de organização simples 2 habitado por uma só pessoa ou uma só família. 〈μόνος, ῥυθμός〉</p></section></article>\n<article id=\"entry-dgp-27482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνος,</h1><div class=\"entry-meta\"><span>DGP · ordem 1903 na letra μ · nº geral 27482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. μοῦνος, η, ον 1 só; isolado de, gen. ou ἀπό e gen.: μόνην μὴ πρόλειπε ésql. não me deixes sozinha, σοῦ μόνος sóf. privado de ti, sem ti, κεῖται μοῦνος ἀπ’ ἄλλων sóf. permanece isolado dos demais 2 único entre, gen.: εἷς μοι μοῦνος τυγχάνεις ἐὼν παῖς her. calhas de ser meu único filho, τὴν σὴν ὄμαιμον μοῦνος Ἑλλήνων ἔτλη θῦσαι θεοῖσιν sóf. foi o único entre os helenos a ter coragem de sacrificar tua irmã aos deuses, no superl. μονώτατος γὰρ εἶ σὺ πάντων αἴτιος ar. és o único responsável por tudo isso 3 ♦ μόνον adv. apenas: οὐ μόνον… ἀλλὰ καί át. não apenas… mas ainda, οὐ μόνον ou οὐ μόνον οὐ não somente… não, οὐ μόνον ou μόνον οὐχί ou μονονουχί luc. pouco falta para, quase 4 apenas, pelo menos, com opt. ou imper.: μόνον μή xen. para que… não, desde que… não, a menos que… 5 ♦ κατὰ μόνας por si só; sozinho; individualmente: ἄρχειν δὲ κατὰ μόνας οὐκ ἐῶσιν artt. não permitem que elas [as cidades] tenham seu próprio governo. 〈*μονϜός〉</p></section></article>\n<article id=\"entry-dgp-27483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοσιτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1904 na letra μ · nº geral 27483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comer uma só vez ao dia. 〈μόνος, σιτέω〉</p></section></article>\n<article id=\"entry-dgp-27484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοστιβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1905 na letra μ · nº geral 27484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que caminha só; solitário. 〈μόνος, στείβω〉</p></section></article>\n<article id=\"entry-dgp-27485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόστιχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1906 na letra μ · nº geral 27485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">composto de um só verso. 〈μόνος, στίχος〉</p></section></article>\n<article id=\"entry-dgp-27486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόστολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1907 na letra μ · nº geral 27486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só; solitário. 〈μόνος, στόλος〉</p></section></article>\n<article id=\"entry-dgp-27487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοτράπεζος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1908 na letra μ · nº geral 27487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se coloca sobre uma mesa em separado. 〈μόνος, τράπεζα〉</p></section></article>\n<article id=\"entry-dgp-27488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονότροπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1909 na letra μ · nº geral 27488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem uma só maneira de ser; de caráter único; simples 2 que tem gostos solitários 3 que vive só; celibatário. 〈μόνος, τρέπω〉</p></section></article>\n<article id=\"entry-dgp-27489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοφάγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1910 na letra μ · nº geral 27489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que come só; glutão; egoísta. 〈μόνος, φαγεῖν〉</p></section></article>\n<article id=\"entry-dgp-27490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόφθαλμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1911 na letra μ · nº geral 27490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem um olho apenas. 〈μόνος, ὀφθαλμός〉</p></section></article>\n<article id=\"entry-dgp-27491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόφρουρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1912 na letra μ · nº geral 27491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guardião único; defensor único. 〈μόνος, φρουρά〉</p></section></article>\n<article id=\"entry-dgp-27492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1913 na letra μ · nº geral 27492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que tem julgamento próprio; que tem idéias próprias. 〈μόνος, φρήν〉</p></section></article>\n<article id=\"entry-dgp-27493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονοφυής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1914 na letra μ · nº geral 27493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem uma só natureza 2 único; singular; simples. 〈μόνος, φύω〉</p></section></article>\n<article id=\"entry-dgp-27494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόχαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1915 na letra μ · nº geral 27494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. que tem o casco inteiriço, não-fendido. 〈μόνος, χηλή〉</p></section></article>\n<article id=\"entry-dgp-27495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόψηφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1916 na letra μ · nº geral 27495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que é único em seu modo de pensar; cuja opinião é única 2 que decide por si só; que se basta na decisão. 〈μόνος, ψῆφος〉</p></section></article>\n<article id=\"entry-dgp-27496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1917 na letra μ · nº geral 27496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 reduzir a um 2 isolar; deixar só 3 manter separado dos demais ♦ pas. 4 ser deixado só ou abandonado de, gen.: γυνὴ μονωθεῖσ’ οὐδέν ésql. uma mulher, deixada só, nada vale 5 ficar separado ou isolado de gen. ou ἀπό e gen.: μόνη, μονωθεῖσ’ ἀπὸ πατρὸς καὶ μητέρος eur. sozinha, separada do pai e da mãe 6 ser privado de, gen. 〈μόνος〉</p></section></article>\n<article id=\"entry-dgp-27497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονῳδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1918 na letra μ · nº geral 27497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐμονῴδουν, fut. μονῳδήσω etc.) cantar só, sem acompanhamento; cantar uma monodia. 〈μό­νος, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-27498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μονῳδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1919 na letra μ · nº geral 27498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de cantar só, sem acompanhamento; monodia. 〈μόνος, ᾠδή〉</p></section></article>\n<article id=\"entry-dgp-27499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνως</h1><div class=\"entry-meta\"><span>DGP · ordem 1920 na letra μ · nº geral 27499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. somente.</p></section></article>\n<article id=\"entry-dgp-27500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μόνωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1921 na letra μ · nº geral 27500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 solidão; isolamento 2 abandono; separação. 〈μονόω〉</p></section></article>\n";
